Let $\mathscr{D} = (d_1 \geqslant d_2 \geqslant \dots \geqslant d_n)$ be the graphic degree sequence of a tree. The \emph{greedy tree} $T_\mathscr{D}$ is constructed as follows:

\begin{enumerate}
  \item Start with a single vertex $v_1$ of target degree $d_1$.
  \item For $i=2,\dots,n$: Create a new vertex $v_i$ of target degree $d_i$. Connect $v_i$ to the vertex $u$ in the current tree that has the \emph{smallest current degree} among all vertices that have not yet reached their target degree (see Figure~\ref{fig001greedy}).
\end{enumerate}

~\label{problemnumber1}
Consider a tree $\mathcal{T}$ assuming $n \geq 3$ where
\begin{itemize}
\item Spine vertices: $v_1, \dots, v_n$, with degrees $p+1$ for $v_1$ and $v_n$, and $p+2$ for the internal spine vertices.
\item First-level pendants: each of degree $1+r$.
\item Second-level pendants: each of degree $1+s$.
\item Third-level pendants (leaves): each of degree $1$.
\end{itemize} 
Determine $\sigma$- irregularity index for the tree $\mathcal{T}$.

~\label{TmuDisu01min}
Let $\mathcal{T}_n$ be the family of all trees on $n$ vertices where $n \geq 3$.
Among all trees on $n$ vertices that are neither caterpillars nor greedy trees. Then, 
\begin{align*}
&\min\{\sigma(\mathcal{T})\mid \mathcal{T}\in \mathcal{T}_n; \text{ if } \mathcal{T} \text{ is caterpillar tree}\}>\min\{\sigma(\mathcal{T})\mid \mathcal{T}\in \mathcal{T}_n\}\\
&\min\{\sigma(\mathcal{T})\mid \mathcal{T}\in \mathcal{T}_n; \text{ if } \mathcal{T} \text{ is greedy tree}\}\geqslant \min\{\sigma(\mathcal{T})\mid \mathcal{T}\in \mathcal{T}_n\}.
\end{align*}
 There exist non-caterpillar, non-greedy trees $\mathcal{T}$ on $n$ vertices such that
 \begin{equation}~\label{eqq1TmuDisu01min}
\min\bigl\{\sigma(\mathcal{S})\mid \mathcal{S}\in\mathcal{T}_n\bigr\}<\sigma(\mathcal{T})<\min\bigl\{\sigma(\mathcal{S})\mid \mathcal{S}\in\mathcal{T}_n\bigr\} 
 \end{equation}
 where $\mathcal{S}$ is a caterpillar tree.

~\label{pro.sig.1}
The Sigma index of the caterpillar tree $\mathbb{C}(n,m)$ of order $(n,m)$ is given by:
\[
\sigma(\mathbb{C}(n,m)) = \begin{cases}
2m^3, & \quad \text{if } n = 2, \\
2m^3 + m\,.n\,(m+1)^2+2, & \quad \text{if } n> 2.
\end{cases}
\]

\label{le.segma3}
Let $\mathbb{C}$ be a caterpillar tree with degree sequence $ \mathscr{D} = (d_1, d_2, d_3) $, where $ d_3 \geqslant d_2 \geqslant d_1 $. Then, the Sigma index of $ T $ is given by:
\begin{equation}~\label{eqle.segma3n1}
\sigma(\mathbb{C})=\sum_{i=1}^{3} p\,(d_i-1)^2+\sum_{i=1}^{2}(d_i-d_{i+1})^2.
\end{equation}

Let $\mathbb{C}$ be a caterpillar tree with an increasing degree sequence $\mathscr{D} = (d_1, d_2, d_3)$ and pendent vertices $p$. To prove \eqref{eqle.segma3n1}, we consider the following valid cases. Suppose the degree sequence is $\mathscr{D}$ ordered such that $(d_1, d_2, d_3)$. Then, we have:
\begin{equation}~\label{eqq1le.segma3}
 \sigma(\mathbb{C})=p(d_1-1)^2+p(d_2-1)^2+p(d_3-1)^2+(d_1-d_2)^2+(d_2-d_3)^2  
\end{equation}
If $d_1=d_2=d_3=k$. Then, $\sigma(\mathbb{C})=3p\,(k-1)^2$. Now, consider the degree sequence $\mathscr{D}$ ordered such that $(d_2, d_1, d_3)$. We obtain:
\begin{equation}~\label{eqq2le.segma3}
 \sigma(\mathbb{C})=p(d_1-1)^2+p(d_2-1)^2+p(d_3-1)^2+(d_2-d_1)^2+(d_1-d_3)^2   
\end{equation}
If $d_1=d_2=d_3=k$. Then, $\sigma(\mathbb{C})=3p\,(k-1)^2$. Thus, if the degree sequence $\mathscr{D}$ ordered such that$(d_1, d_3, d_2)$. We obtain:
\begin{equation}~\label{eqq3le.segma3}
 \sigma(\mathbb{C})=p(d_1-1)^2+p(d_2-1)^2+p(d_3-1)^2+(d_1-d_3)^2+(d_3-d_2)^2  
\end{equation}
Thus, from~\eqref{eqq2le.segma3}--\eqref{eqq3le.segma3} we find that 
\[
\sigma(\mathbb{C})=\begin{cases}
\sigma_{\max}(\mathbb{C})=p(d_1-1)^2+p(d_2-1)^2+p(d_3-1)^2+(d_1-d_3)^2+(d_3-d_2)^2 , \\
\sigma_{\min}(\mathbb{C})=p(d_1-1)^2+p(d_2-1)^2+p(d_3-1)^2+(d_1-d_2)^2+(d_2-d_3)^2.
\end{cases}
\]
This completes the proof.

~\label{TypeLemman1s}
Consider $\mathcal{T}$ be a tree given by Problem~\ref{problemnumber1} with spine vertices $v_1,v_2,\dots,v_n$ where $n\geqslant 3$. Then, the $\sigma$-irregularity index of $\mathcal{T}$ is
\begin{equation}~\label{eqq1TypeLemman1s}
\sigma(\mathcal{T})=nprs^3+p(n-2)(p+1-r)^2+2p(p-r)^2+npr(r-s)^2+2.
\end{equation}

Assume $\mathcal{T}$ be a tree with a spine, vertices on three levels, such that the first-level pendants each have degree $1+r$, the second-level pendants each have degree $1+s$, and the third-level pendants (leaves) each have degree $1$. For the spine edges, we find that there are $n-1$ edges. Thus, for  $i=1$ and $i=n-1$ the degrees are $p+1$ and $p+2$ implies that $(p+1-(p+2))^2=1$. For $i=2,\dots,n-2$ both endpoints have degree $p+2$ implies that $(p+2-(p+2))^2=0$. Now, to determine the value of edges between spine vertices and first-level pendants, we noticed that the edges incident to $v_1$ or $v_n$ (there are $2p$ of them), the degrees $p+1$ and $1+r$ implies that $(p+1-(1+r))^2=(p-r)^2$ yields $2\,(p-r)^2$. Also, for edges incident to internal spine vertices $v_2,\dots,v_{n-1}$ (there are $(n-2)p$ of them), the degrees $p+2$ and $1+r$ implies that $(p+2-(1+r))^2=(p+1-r)^2$ yields $2\,(p+1-r)^2$. Thus, 
\begin{equation}~\label{eqq2TypeLemman1s}
\sigma(\mathcal{T}_1)=2\,(p-r)^2+2\,(p+1-r)^2+2.
\end{equation}
For other levels, there are $npr$ such edges for the second level. Thus, both endpoints have degrees $1+r$ and $1+s$ implies that $((1+r)-(1+s))^2=(r-s)^2$ yields $npr(r-s)^2.$ To determine the edges between second-level pendants and leaves, we noticed that there are $nprs$ such edges. Thus, for the degrees are $1+s$ and $1$ implies that $((1+s)-1)^2=s^2,$ yields $nprs^3.$ Thus, 
\begin{equation}~\label{eqq3TypeLemman1s}
\sigma(\mathcal{T}_2)=npr(r-s)^2+nprs^3.
\end{equation}
Therefore, from~\eqref{eqq2TypeLemman1s} and \eqref{eqq3TypeLemman1s} we obtain on $\sigma(\mathcal{T})=\sigma(\mathcal{T}_1)+\sigma(\mathcal{T}_2).$ Thus, the relationship~\eqref{eqq1TypeLemman1s} holds. This completes the proof.

~\label{TypeLemman2s}
Consider $\mathcal{T}$ be a tree with spine vertices $v_1,v_2,\dots,v_n$ where $n\geqslant 3$ and the following degree structure based on Problem~\ref{problemnumber1}. Each first-level pendant vertex has degree $(1+r)^2$. Each second-level pendant vertex has degree $(1+s)^2$ and is adjacent to exactly $(1+s)^2 - 1$ leaves (third-level pendants), each of degree $1$. Then, the $\sigma$-irregularity index of $\mathcal{T}$ is
\begin{equation}~\label{eqq1TypeLemman2s}
\sigma(\mathcal{T})=\mu_0-(1+s)^2)^2+np\,((1+r)^2-1)\,((1+s)^2-1)^3+\mu_1+2,
\end{equation}
where $\mu_0=np\,((1+r)^2-1)\,((1+r)^2$ and $\mu_1=2p\,(p-(1+r)^2+1)^2+p(n-2)\,(p+1-(1+r)^2)^2$.

Assume $\mathcal{T}$ be a tree with a spine, vertices on three levels, according to Lemma~\ref{TypeLemman1s}, the first-level pendants each have degree $(1+r)^2$, the second-level pendants each have degree $(1+s)^2$, and the third-level pendants (leaves) each have degree $1$. Thus, 
\begin{equation}~\label{eqq2TypeLemman2s}
\sigma(\mathcal{T}_1)=2p\,(p-(1+r)^2+1)^2+p(n-2)\,(p+1-(1+r)^2)^2.
\end{equation}
Similarly, for the first and second level, each of the $np$ first-level pendants has degree $(1+r)^2$, one edge goes to the spine, so it has $(1+r)^2- 1$ children implies that $np((1+r)^2-1)$ and  each such edge connects a vertex of degree $(1+r)^2$ to a vertex of degree $(1+s)^2$ implies that $((1+r)^2-(1+s)^2)^2$ yields $np\,((1+r)^2-1)\,((1+r)^2-(1+s)^2)^2.$ Also, to determine the value of the second level to leaf edges, we find that each of the $np((1+r)^2-1)$ second-level pendants has degree $(1+s)^2$, one edge to its parent (first-level), so it has $(1+s)^2-1$ leaves. Thus there are
$np\,((1+r)^2-1)\,((1+s)^2-1)$ such edges. Therefore, we have 
\begin{equation}~\label{eqq3TypeLemman2s}
\sigma(\mathcal{T}_2)=np\,((1+r)^2-1)\,((1+s)^2-1)^3.
\end{equation}
Hence, from~\eqref{eqq2TypeLemman2s} and \eqref{eqq3TypeLemman2s} we obtain on $\sigma(\mathcal{T})=\sigma(\mathcal{T}_1)+\sigma(\mathcal{T}_2).$ Thus, the relationship~\eqref{eqq1TypeLemman2s} holds. This completes the proof.

~\label{TypeLemman3s}
Let $\mathcal{T}$ be a tree with spine vertices $v_1,v_2,\dots,v_n$ where $n\geqslant 3$ and the following degree structure based on Problem~\ref{problemnumber1}. Each first-level pendant vertex has degree $2p$. Each second-level pendant vertex has degree $2p^2$ and is adjacent to exactly $2p^2-1$ leaves (third-level pendants), each of degree $1$. Then, the $\sigma$-irregularity index of $\mathcal{T}$ is
\begin{equation}~\label{eqq1TypeLemman3s}
\sigma(\mathcal{T})=np(2p-1)(2p^2-1)^3+2p(1-p)^2+p(n-2)(2-p)^2+\mu+2,
\end{equation}
where $\mu=np(2p-1)(2p-2p^2)^2$.

Assume  $\mathcal{T}$ be a tree with spine vertices $v_1,v_2,\dots,v_n$ where $n\geqslant 3$. For the spine vertices and to the first level according to Lemma~\ref{TypeLemman1s} we find that 
\begin{equation}~\label{eqq2TypeLemman3s}
\sigma(\mathcal{T}_1)=2p\,(1-p)^2+p\,(n-2)(2-p)^2.
\end{equation}
Then, at the second level, each of the $np$ first-level pendant vertices is adjacent to exactly $2p-1$ second-level pendant vertices. Thus, there are $np(2p-1)$ edges connecting the first level to the second level. Each such edge joins a vertex of degree $2p$ to a vertex of degree $2p^2$, contributing $(2p^2 - 2p)^2 = 4p^2(p-1)^2$ to the $\sigma$-irregularity index. Therefore, the total contribution from these edges is
\begin{equation} \label{eqq3TypeLemman3s}
\sigma(\mathcal{T}_2)=np(2p-1)(2p^2-2p)^2.
\end{equation}
Now consider the edges incident to the third level. Each second-level pendant vertex has degree $2p^2$ and is adjacent to exactly $2p^2-1$ leaves of degree 1. Hence, there are $np(2p-1)(2p^2-1)$ such edges, each contributing $(2p^2-1)^2$ to the $\sigma$-irregularity index. The total contribution from these edges is
\begin{equation} \label{eqq4TypeLemman3s}
\sigma(\mathcal{T}_3)=np\,(2p-1)(2p^2-1)^3.
\end{equation}

Finally, combining the contributions from the spine and first level in \eqref{eqq2TypeLemman3s} with those from \eqref{eqq3TypeLemman3s} and \eqref{eqq4TypeLemman3s} yields
\[
\sigma(\mathcal{T})=\sigma(\mathcal{T}_1)+\sigma(\mathcal{T}_2)+\sigma(\mathcal{T}_3),
\]
which gives~\eqref{eqq1TypeLemman3s} and completes the proof.

~\label{le.sigma2}
Let $\mathbb{C}$ be a caterpillar tree of order $n$, and let $\mathscr{D} = (d_1, d_2, d_3, d_4)$ be a degree sequence, where $d_4 \geqslant d_3 \geqslant d_2 \geqslant d_1$. Then, 
\[
\sigma(\mathbb{C})=\begin{cases}
\sigma_{\max}(\mathbb{C})=p \sum_{i=1}^{4} (d_i-1)^2+(d_4-d_1)^2+(d_1-d_3)^2+(d_3-d_2)^2, \\
 \sigma_{\min}(\mathbb{C})= p \sum_{i=1}^{4} (d_i-1)^2+(d_1-d_2)^2+(d_2-d_3)^2+(d_3-d_4)^2.
\end{cases}
\]

~\label{maThmn1cater}
Let $\mathcal{T}$ be a tree with $n \geq 3$ vertices given by Problem~\ref{problemThnumber2}, consisting of a spine $v_1, v_2, \dots, v_n$ and exactly $k$ levels of pendants. The $\sigma$-irregularity index is
\begin{equation}~\label{eqq1maThmn1cater}
\sigma(T)=\sum_{\ell=1}^{k-1} np\Bigl(\prod_{j=1}^{\ell-1}(d_j-1)\Bigr)(d_\ell-d_{\ell+1})^2+np\Bigl(\prod_{j=1}^{k-2}(d_j-1)\Bigr)(d_{k-1}-1)^2+\mu,
\end{equation}
where $\mu=2+\,2p(p+1-d_1)^2+p(n-2)(p+2-d_1)^2$.

The vertices of $\mathcal{T}$ are partitioned into levels such that level $0$ consists of the spine vertices, while level $\ell$ satisfying $1\leqslant\ell\leqslant k$ contains all vertices at distance $\ell$ from the spine. Edges exist only between consecutive levels. Hence, we consider each spine vertex has exactly $m_0=p$ neighbors in level $1$. Consequently, the total number of edges between levels $0$ and $1$ is $np$.
For $\ell \geqslant 1$, every vertex in level $\ell$ has exactly $m_\ell=d_\ell-1$ pendent vertices in level $\ell+1$. Thus, the number of edges between levels $\ell$ and $\ell+1$ is
\begin{equation}~\label{eqq2maThmn1cater}
\mathcal{E}_{\ell,\ell+1}=np\,\prod_{j=1}^{\ell-1} (d_j-1).
\end{equation}
Therefore, from~\eqref{eqq2maThmn1cater} we noticed that
\begin{equation}~\label{eqq3maThmn1cater}
\sigma(\mathcal{T})=\sigma_{0,1}(\mathcal{T})+\sum_{\ell=1}^{k-1}\sigma_{\ell,\ell+1}(\mathcal{T}),
\end{equation}
where $\sigma_{\ell,\ell+1}$ denotes the the terms arising from the edges connecting levels $\ell$ and $\ell+1$. For $\ell=1$, each spine vertex has exactly $p$ neighbors in level $1$. As there are $n$ spine vertices, the total number of edges between levels $1$ and $2$ is $np$. Each such edge connects a vertex of degree $d_1$ (in level $1$) to a vertex of degree $d_2$ (in level $2$). Then, $\sigma_{1,2}(\mathcal{T})=np\,(d_1-d_2)^2.$

Therefore, for $1 \leqslant \ell \leqslant k-2$, each edge connecting a vertex at level $\ell$ to a vertex at level $\ell+1$ contributes $(d_\ell-d_{\ell+1})^2$ to~\eqref{eqq3maThmn1cater}.  Therefore, according to~\eqref{eqq3maThmn1cater} we find that
\begin{equation}~\label{eqq4maThmn1cater}
\sigma_{\ell,\ell+1}(\mathcal{T})=np\,\Bigl(\prod_{j=1}^{\ell-1} (d_j-1)\Bigr)(d_\ell-d_{\ell+1})^2.
\end{equation}
Then, from~\eqref{eqq4maThmn1cater} by considering $\ell=k-1$, it satisfies the property that every vertex at level $k$ is a leaf of degree 1. Thus, 
\begin{equation}~\label{eqq5maThmn1cater}
\sigma_{k-1,k}(\mathcal{T})=np\,\Bigl(\prod_{j=1}^{k-2} (d_j-1)\Bigr)\,(d_{k-1}-1)^2.
\end{equation}

Now, for establishing $\sigma_{0,1}(\mathcal{T})$, we noticed that each edge between a spine vertex and a level-1 vertex contributes $(d_0-d_1)^2$, where $d_0$ denotes the degree of the spine vertex. Hence, two endpoint spine vertices $v_1$ and $v_n$ each have degree $d_0 = p+1$ and $p$ neighbors at level 1. Their combined contribution is therefore  
  $2p(p+1-d_1)^2$. Then, each of the $n-2$ internal spine vertices has degree $d_0 = p+2$ and $p$ neighbors at level 1 yields $p(n-2)(p+2-d_1)^2$. Additionally, the two spine edges $v_1v_2$ and $v_{n-1}v_n$ contribute $2$. Therefore,
\begin{equation}~\label{eqq6maThmn1cater}
\sigma_{0,1}(\mathcal{T})=2p(p+1-d_1)^2+p(n-2)(p+2-d_1)^2+2.
\end{equation}
Thus, in this case if we consider $\mu=\sigma_{0,1}(\mathcal{T})$ both of~\eqref{eqq5maThmn1cater} and \eqref{eqq6maThmn1cater} implies that the relationship~\eqref{eqq3maThmn1cater}. Therefore, the relationship~\eqref{eqq1maThmn1cater} holds.

~\label{TnpowPronu4}
Let $\mathbb{C}$ be a caterpillar tree, and let $\mathscr{D} = (d_1, d_2, \dots, d_n)$ be a degree sequence where $d_1 \geqslant d_2 \geqslant \dots \geqslant d_n$, with maximum degree $\Delta$, minimum degree $\delta \geqslant 2$, and let $\lambda_{\mathscr{D}}$ be the average of $\mathscr{D}$. Then, the upper bound of the Sigma index satisfies
\begin{equation}~\label{eq1TnpowPronu4}
\sigma(\mathbb{C})\leqslant \sum_{i=1}^{n-1}\lambda_{\mathscr{D}}(d_i-d_{i+1})^3 +2(n^2+m^2)+3m+n+2.
\end{equation}
